                    "entity_list": "\n".join(node_details[:40])
                })
                self.community_summaries[comm_id] = summary
            except Exception as e:
                logger.error(f"Error generating summary for community {comm_id}: {e}")
                self.community_summaries[comm_id] = "Unable to generate summary."

        return self.community_summaries

def get_node_community(self, node_id: str) -> Optional[int]:
        for comm_id, nodes in self.communities.items():
            if node_id in nodes:
                return comm_id
        return None

def save_results(self, output_path: str):
        results = {
            "communities": self.communities,
            "summaries": self.community_summaries,
        }
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump(results, f, ensure_ascii=False, indent=2)

def split_text(self, text: str, metadata: dict) -> list[Document]:
        ext = Path(metadata.get("source", "")).suffix.lower()
        if ext in (".md", ".mdx", ".markdown", ".rst"):
            return self._split_markdown(text, metadata)
        return self._split_by_paragraph(text, {**metadata, "chunk_type": "plain_text"})

def _split_markdown(self, text: str, base_meta: dict) -> list[Document]:
        # 第一步：提取代码块，用占位符保护，避免内部内容被误判为标题/段落边界
        specials: dict[str, str] = {}
        counter = [0]

        def _extract(m: re.Match) -> str:
            key = f"\x00SPECIAL{counter[0]}\x00"
            specials[key] = m.group(0)
            counter[0] += 1
            return key

        protected = self._CODE_FENCE_RE.sub(_extract, text)

        # 第二步：按标题切分为 sections
        sections = self._parse_heading_sections(protected)

        # 第三步：每个 section 还原占位符，按尺寸决定是否细切
        docs: list[Document] = []
        for sec in sections:
            content = sec["content"]
            for key, val in specials.items():
                content = content.replace(key, val)
            content = content.strip()
            if not content:
                continue

            heading_meta = {
                **base_meta,
                "chunk_type": "markdown_section",
                "section_heading": sec["heading"],
                "heading_level": sec["level"],
                "breadcrumb": " > ".join(sec["breadcrumb"]),
            }

            if len(content) <= self.MAX_CHUNK_SIZE:
                docs.append(Document(page_content=content, metadata=heading_meta))
            else:
                docs.extend(self._split_by_paragraph(content, heading_meta))

        return docs

def flush():
            content_raw = "".join(current_lines)
            breadcrumb = [h for _, h in heading_stack]
            heading_prefix = f"{'#' * current_level} {current_heading}\n\n" if current_heading else ""
            sections.append({
                "heading": current_heading,
                "level": current_level,
                "content": heading_prefix + content_raw,
                "breadcrumb": breadcrumb,
            })

def _split_by_paragraph(self, text: str, base_meta: dict) -> list[Document]:
        """按空行段落边界切分，超长段落进一步按句子切。"""
        paragraphs = re.split(r'\n\s*\n', text)
        docs: list[Document] = []
        current_chunk = ""
        chunk_idx = 0

        for para in paragraphs:
            para = para.strip()
            if not para:
                continue

            # 单个段落本身超长且不是代码块 → 按句子细切
            if len(para) > self.MAX_CHUNK_SIZE and not para.startswith("```"):
                if current_chunk:
                    docs.append(Document(
                        page_content=current_chunk.strip(),
                        metadata={**base_meta, "chunk_index": chunk_idx},
                    ))
                    chunk_idx += 1
                    current_chunk = ""
                sent_docs = self._split_by_sentence(para, base_meta, chunk_idx)
                docs.extend(sent_docs)
                chunk_idx += len(sent_docs)
                continue

            if len(current_chunk) + len(para) + 2 > self.MAX_CHUNK_SIZE:
                if current_chunk:
                    docs.append(Document(
                        page_content=current_chunk.strip(),
                        metadata={**base_meta, "chunk_index": chunk_idx},
                    ))
                    chunk_idx += 1
                    # 尾部 overlap：保留上一块末尾内容，帮助上下文连续
                    overlap = current_chunk[-self.OVERLAP_SIZE:] if len(current_chunk) > self.OVERLAP_SIZE else current_chunk
                    current_chunk = overlap + "\n\n" + para
                else:
                    current_chunk = para
            else:
                current_chunk = (current_chunk + "\n\n" + para).strip() if current_chunk else para

        if current_chunk.strip():
            docs.append(Document(
                page_content=current_chunk.strip(),
                metadata={**base_meta, "chunk_index": chunk_idx},
            ))

        return docs

def _split_by_sentence(self, text: str, base_meta: dict, start_idx: int) -> list[Document]:
        sentences = self._SENTENCE_SPLIT_RE.split(text)
        docs: list[Document] = []
        current = ""
        idx = start_idx

        for sent in sentences:
            sent = sent.strip()
            if not sent:
                continue
            if len(current) + len(sent) + 1 > self.MAX_CHUNK_SIZE:
                if current:
                    docs.append(Document(
                        page_content=current.strip(),
                        metadata={**base_meta, "chunk_index": idx, "chunk_type": "sentence_fallback"},
                    ))
                    idx += 1
                current = sent
            else:
                current = (current + " " + sent).strip() if current else sent

        if current.strip():
            docs.append(Document(
                page_content=current.strip(),
                metadata={**base_meta, "chunk_index": idx, "chunk_type": "sentence_fallback"},
            ))

        return docs

def flush_pending():
        nonlocal pending_content, pending_meta
        if pending_content and pending_meta is not None:
            result.append(Document(page_content=pending_content.strip(), metadata=pending_meta))
        pending_content = ""
        pending_meta = None

class CategoryRetrievalUnit:
    dense_store: "FAISS"
    sparse_index: SparseBM25Index | None

class CachedStoreEntry:
    """缓存的向量库条目"""
    stores: Dict[str, CategoryRetrievalUnit]
    created_at: float = field(default_factory=time.time)
    last_accessed: float = field(default_factory=time.time)

    def is_expired(self) -> bool:
        return time.time() - self.created_at > CACHE_TTL_SECONDS

    def touch(self) -> None:
        self.last_accessed = time.time()

def __init__(self, max_entries: int = CACHE_MAX_ENTRIES):
        self._cache: Dict[str, CachedStoreEntry] = {}
        self._lock = threading.RLock()
        self._max_entries = max_entries

def invalidate(self, root_path: str) -> None:
        """使指定路径的缓存失效"""
        with self._lock:
            if root_path in self._cache:
                del self._cache[root_path]
                logger.info(f"[VectorStoreCache] Invalidated cache for {root_path}")

def stats(self) -> Dict[str, any]:
        """返回缓存统计信息"""
        with self._lock:
            return {
                "entries": len(self._cache),
                "max_entries": self._max_entries,
                "paths": list(self._cache.keys())
            }

def _ensure_api_key() -> None:
    """检查 OpenRouter API Key 是否设置"""
    api_key = os.getenv("OPENROUTER_API_KEY")
    if not api_key:
        raise ValueError(
            "OPENROUTER_API_KEY environment variable not set. Please set it before running."
        )

def _resolve_vector_store_root(base_path: str) -> str:
    """
    校验并返回向量库根目录。
    """
    if not base_path:
        raise ValueError(
            "Set VECTOR_STORE_PATH to the vector store root or a specific category directory."
        )

    candidate = os.path.abspath(base_path)
    if not os.path.exists(candidate):
        raise FileNotFoundError(f"Vector store directory does not exist: {candidate}")
    return candidate

def _extract_store_documents(store: "FAISS") -> List[Document]:
    """
    从 FAISS 向量库中提取所有缓存的 Document 对象。
    这些文档用于构建稀疏检索索引（BM25）和执行 MMR（最大边际相关性）选择。
    返回文档的副本列表，包含内容和元数据。
    """
    docstore = getattr(store, "docstore", None)
    if docstore is None:
        return []

    raw_docs: Iterable[Document]
    if hasattr(docstore, "_dict"):
        raw_docs = docstore._dict.values()  # type: ignore[attr-defined]
    else:
        raw_docs = []

    extracted: List[Document] = []
    for doc in raw_docs:
        if not isinstance(doc, Document):
            continue
        extracted.append(Document(page_content=doc.page_content, metadata=dict(doc.metadata)))
    return extracted

def invalidate_vector_store_cache(root_path: Optional[str] = None) -> None:
    """
    使向量库缓存失效。

    Args:
        root_path: 指定要失效的路径，None 表示清空所有缓存
    """
    if root_path:
        _vector_store_cache.invalidate(root_path)
    else:
        _vector_store_cache.clear()

def get_vector_store_cache_stats() -> Dict[str, any]:
    """获取向量库缓存统计信息"""
    return _vector_store_cache.stats()

def _format_documents(docs: List[Document]) -> str:
    """
    将检索到的文档列表格式化为可读的字符串格式。
    每个文档包含片段编号、类型和来源信息，用于构建 RAG 提示的上下文。
    返回格式化后的字符串，文档之间用双换行分隔。
    """
    if not docs:
        return ""

    formatted_chunks: List[str] = []
    for idx, doc in enumerate(docs, start=1):
        source = doc.metadata.get("source") or doc.metadata.get("file_path") or ""
        category = doc.metadata.get("kb_category", "")
        header_parts = [f"[chunk {idx}]"]
        if category:
            header_parts.append(f"type: {category}")
        if source:
            header_parts.append(f"source: {source}")
        header = " | ".join(header_parts)
        formatted_chunks.append(f"{header}\n{doc.page_content.strip()}")
    return "\n\n".join(formatted_chunks)

def _load_graphrag_communities(
    root_path: str,
) -> Optional[Tuple[Dict[int, List[str]], Dict[int, str]]]:
    """
    读取与向量库同目录下的 GraphRAG 社区划分与摘要（wiki 流程中由 struct_gen 生成并写入）。
    """
    path = os.path.join(root_path, GRAPHRAG_COMMUNITIES_FILENAME)
    if not os.path.isfile(path):
        return None
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        comm_raw = data.get("communities") or {}
        summ_raw = data.get("summaries") or {}
        communities: Dict[int, List[str]] = {}
        for k, v in comm_raw.items():
            try:
                cid = int(k)
            except (TypeError, ValueError):
                continue
            if isinstance(v, list):
                communities[cid] = [str(x) for x in v]
        summaries: Dict[int, str] = {}
        for k, v in summ_raw.items():
            try:
                cid = int(k)
            except (TypeError, ValueError):
                continue
            summaries[cid] = str(v) if v is not None else ""
        if not communities or not summaries:
            return None
        return communities, summaries
    except (OSError, json.JSONDecodeError, TypeError) as e:
        logger.warning("[RAG] 无法加载 GraphRAG 元数据 %s: %s", path, e)
        return None

def _collect_all_store_documents(
    stores: Mapping[str, CategoryRetrievalUnit],
) -> List[Document]:
    combined: List[Document] = []
    for category, unit in stores.items():
        for doc in _extract_store_documents(unit.dense_store):
            combined.append(_attach_category(doc, category))
    return combined

def _gather_dense_faiss_hits(
    stores: Mapping[str, CategoryRetrievalUnit],
    question: str,
    *,
    category_top_k: Mapping[str, int],
) -> List[Tuple[Document, float]]:
    """
    仅稠密向量检索命中（跨类别合并），供 CommunityFirstRetriever.hybrid_retrieve 与社区稀疏分融合。
    """
    best_by_key: Dict[str, Tuple[Document, float]] = {}
    for category, unit in stores.items():
        planned_base = max(int(category_top_k.get(category, 0)), 1)
        dense_k = _plan_method_k(planned_base, DENSE_K_MULTIPLIER)
        dense_hits = unit.dense_store.similarity_search_with_relevance_scores(
            question, k=dense_k
        )
        for doc, score in dense_hits:
            enriched = _attach_category(doc, category)
            key = f"{category}|{compute_doc_key(enriched)}"
            prev = best_by_key.get(key)
            if prev is None or float(score) > prev[1]:
                best_by_key[key] = (enriched, float(score))
    if not best_by_key:
        return []
    return sorted(best_by_key.values(), key=lambda x: x[1], reverse=True)

def _gather_retrieval_candidates(
    stores: Mapping[str, CategoryRetrievalUnit],
    question: str,
    *,
    category_top_k: Mapping[str, int],
    graphrag: Optional[Tuple[Dict[int, List[str]], Dict[int, str]]] = None,
) -> List[RankedCandidate]:
    """
    若存在 GraphRAG 元数据，则用 CommunityFirstRetriever 做社区优先两阶段稀疏检索，
    并与全库稠密向量分按 HYBRID_DENSE_WEIGHT 融合；否则保持原按类 BM25+稠密混合。
    """
    if graphrag:
        communities, summaries = graphrag
        all_docs = _collect_all_store_documents(stores)
        if all_docs:
            try:
                retriever = create_community_retriever(communities, summaries, all_docs)
                dense_hits = _gather_dense_faiss_hits(
                    stores, question, category_top_k=category_top_k
                )
                merged = retriever.hybrid_retrieve(
                    question,
                    dense_hits,
                    top_k_communities=3,
                    top_k_docs_per_community=5,
                    alpha=HYBRID_DENSE_WEIGHT,
                    top_k=MAX_TOTAL_CANDIDATES,
                )
                if merged:
                    logger.info("[RAG] 已启用 CommunityFirstRetriever 主路径（GraphRAG + 稠密）")
                    return merged
            except Exception as exc:
                logger.warning("[RAG] CommunityFirstRetriever 不可用，回退混合检索: %s", exc)

    return _gather_hybrid_candidates(
        stores, question, category_top_k=category_top_k
    )

def interactive_chat(
    db_path: str, *, category_top_k: Mapping[str, int] | None = None
) -> None:
    """
    启动命令行交互式对话模式，用于快速验证 RAG 问答效果。
    持续接收用户输入的问题，返回 AI 答案和参考来源，直到用户输入 exit/quit 退出。
    """
    root_path = _resolve_vector_store_root(db_path)
    top_k_plan = dict(category_top_k or CATEGORY_TOP_K)
    stores = _load_vector_stores(root_path, top_k_plan.keys())
    graphrag = _load_graphrag_communities(root_path)

    print(
        "Vector store loaded. Type a question (exit/quit to stop). "
        f"Retrieval plan: {', '.join(f'{cat}:{k}' for cat, k in top_k_plan.items())}"
    )

    while True:
        try:
            question = input("Q> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nInterrupted, exiting.")
            break

        if not question:
            continue
        if question.lower() in {"exit", "quit"}:
            print("Goodbye.")
            break

        try:
            result = _answer_with_stores(
                stores,
                question,
                category_top_k=top_k_plan,
                graphrag=graphrag,
            )
        except Exception as exc:
            print(f"Error: {exc}")
            continue

        print("\nAnswer:")
        print(result["answer"])
        if result["sources"]:
            print("\nSources:")
            for src in result["sources"]:
                print(f"- {src}")
        print("-" * 40)

def default_tokenizer(text: str) -> List[str]:
    """
    轻量分词实现，提取匹配的（中文，英文，数字，下划线）
    """
    if not text:
        return []
    return _TOKEN_PATTERN.findall(text.lower())

class SparseBM25Index:
    """
    只依赖轻量分词的 BM25 实现，避免额外依赖和构建流程。
    """

    def __init__(
        self,
        documents: List[Document],
        tokenized_docs: List[List[str]],
        term_freqs: List[Counter[str]],
        idf: Dict[str, float],
        avg_doc_len: float,
        tokenizer: Tokenizer,
    ) -> None:
        self._documents = documents
        self._tokenized_docs = tokenized_docs
        self._term_freqs = term_freqs
        self._idf = idf
        self._avg_doc_len = avg_doc_len
        self._tokenizer = tokenizer
        self._k1 = 1.5
        self._b = 0.75

    @classmethod
    def build(
        cls, documents: Iterable[Document], tokenizer: Tokenizer | None = None
    ) -> "SparseBM25Index":
        tokenizer = tokenizer or default_tokenizer
        docs: List[Document] = []
        tokenized_docs: List[List[str]] = []
        term_freqs: List[Counter[str]] = []
        doc_freqs: Dict[str, int] = defaultdict(int)

        for doc in documents:
            cloned = _clone_document(doc)
            docs.append(cloned)
            tokens = tokenizer(cloned.page_content)
            tokenized_docs.append(tokens)
            freq = Counter(tokens)
            term_freqs.append(freq)
            for term in freq:
                doc_freqs[term] += 1

        if not docs:
            return cls([], [], [], {}, 0.0, tokenizer)

        total_len = sum(len(tokens) for tokens in tokenized_docs)
        avg_len = total_len / len(tokenized_docs) if tokenized_docs else 0.0
        doc_count = len(docs)
        idf: Dict[str, float] = {}
        for term, df in doc_freqs.items():
            idf[term] = math.log(1 + (doc_count - df + 0.5) / (df + 0.5))

        return cls(docs, tokenized_docs, term_freqs, idf, avg_len, tokenizer)

    def search(self, query: str, top_k: int = 20) -> List[Tuple[Document, float]]:
        if not self._documents or top_k <= 0:
            return []
        query_tokens = self._tokenizer(query)
        if not query_tokens:
            return []

        scores: List[Tuple[int, float]] = []
        for idx, freq in enumerate(self._term_freqs):
            if not freq:
                continue
            doc_len = len(self._tokenized_docs[idx]) or 1
            score = 0.0
            for term in query_tokens:
                if term not in freq:
                    continue
                idf = self._idf.get(term)
                if idf is None:
                    continue
                tf = freq[term]
                denom = tf + self._k1 * (1 - self._b + self._b * doc_len / (self._avg_doc_len or 1))
                score += idf * (tf * (self._k1 + 1) / denom)
            if score > 0:
                scores.append((idx, score))

        if not scores:
            return []

        scores.sort(key=lambda item: item[1], reverse=True)
        limited = scores[:top_k]
        return [(self._documents[idx], score) for idx, score in limited]

def build(
        cls, documents: Iterable[Document], tokenizer: Tokenizer | None = None
    ) -> "SparseBM25Index":
        tokenizer = tokenizer or default_tokenizer
        docs: List[Document] = []
