def _cosine(counter_a: Counter[str], counter_b: Counter[str]) -> float:
    if not counter_a or not counter_b:
        return 0.0
    shared = set(counter_a) & set(counter_b)
    if not shared:
        return 0.0
    numerator = sum(counter_a[token] * counter_b[token] for token in shared)
    norm_a = math.sqrt(sum(value * value for value in counter_a.values()))
    norm_b = math.sqrt(sum(value * value for value in counter_b.values()))
    if math.isclose(norm_a, 0.0) or math.isclose(norm_b, 0.0):
        return 0.0
    return numerator / (norm_a * norm_b)

def mmr_select(
    candidates: Sequence[RankedCandidate],
    query: str,
    *,
    top_n: int,
    lambda_mult: float = 0.5,
    tokenizer: Tokenizer | None = None,
) -> List[RankedCandidate]:
    """
    经典 MMR：兼顾单点相关性与候选间的互斥性。
    """
    if not candidates or top_n <= 0:
        return []

    tokenizer = tokenizer or default_tokenizer
    query_counter = Counter(tokenizer(query))
    doc_counters = {cand.key: Counter(tokenizer(cand.doc.page_content)) for cand in candidates}

    selected: List[RankedCandidate] = []
    remaining = list(candidates)

    while remaining and len(selected) < top_n:
        best_idx = 0
        best_score = float("-inf")

        for idx, cand in enumerate(remaining):
            relevance = cand.final_score
            if not query_counter:
                sim_to_query = relevance
            else:
                sim_to_query = _cosine(doc_counters[cand.key], query_counter)
                # 若语义分未能区分，则用最终得分兜底
                if math.isclose(sim_to_query, 0.0):
                    sim_to_query = relevance

            if not selected:
                penalty = 0.0
            else:
                penalty = max(
                    _cosine(doc_counters[cand.key], doc_counters[sel.key])
                    for sel in selected
                )

            mmr_score = lambda_mult * sim_to_query - (1 - lambda_mult) * penalty
            if mmr_score > best_score:
                best_score = mmr_score
                best_idx = idx

        selected.append(remaining.pop(best_idx))

    return selected

def _build_doc_community_mapping(self) -> None:
        """构建文档到社区的映射关系"""
        # 创建节点ID到社区ID的映射
        node_to_community: Dict[str, int] = {}
        for comm_id, nodes in self._communities.items():
            for node in nodes:
                node_to_community[node] = comm_id

        # 将文档分配到对应的社区
        for doc in self._documents:
            source = doc.metadata.get("source", "")
            if not source:
                continue

            # 尝试匹配文档源路径到社区节点
            matched_community = None

            # 直接匹配文件路径
            if source in node_to_community:
                matched_community = node_to_community[source]
            else:
                # 尝试部分路径匹配
                for node_id, comm_id in node_to_community.items():
                    if source.endswith(node_id) or node_id.endswith(source):
                        matched_community = comm_id
                        break
                    # 检查函数/类节点 (格式: file_path:name)
                    if ":" in node_id:
                        file_part = node_id.split(":")[0]
                        if source.endswith(file_part) or file_part.endswith(source):
                            matched_community = comm_id
                            break

            if matched_community is not None:
                self._doc_to_community[compute_doc_key(doc)] = matched_community
                self._community_docs[matched_community].append(doc)

def _build_community_index(self) -> None:
        """为社区摘要构建 BM25 索引"""
        if not self._summaries:
            return

        # 创建社区信息列表
        for comm_id, summary in self._summaries.items():
            nodes = self._communities.get(comm_id, [])
            self._community_info_list.append(CommunityInfo(
                community_id=comm_id,
                summary=summary,
                node_ids=nodes,
            ))

        # 创建虚拟文档用于 BM25 检索
        community_docs = [
            Document(
                page_content=info.summary,
                metadata={"community_id": info.community_id}
            )
            for info in self._community_info_list
        ]

        if community_docs:
            self._community_bm25 = SparseBM25Index.build(community_docs, self._tokenizer)

def _task_marked_cancelled_by_user(supabase_client: SupabaseClient, task_id: str) -> bool:
    """
    用户已通过 /cancel 将任务标为 failed（含 Cancelled）时返回 True，
    避免后台在长时间 run_in_executor 结束后把状态写回 completed 覆盖取消结果。
    """
    try:
        row = supabase_client.get_task(task_id)
    except SupabaseStorageError:
        return False
    if not row:
        return False
    if row.get("status") != TaskStatus.FAILED:
        return False
    err = (row.get("error") or "").lower()
    return "cancel" in err

def _update_progress(task_id: Optional[str], progress: float, step: str):
    """内部辅助函数，同步更新任务进度到 Supabase"""
    if task_id:
        try:
            success = SupabaseClient().update_task_progress(task_id, progress, step)
            if not success:
                logger.warning(f"Task {task_id} not found (likely deleted), aborting...")
                raise InterruptedError(f"Task {task_id} was deleted.")
        except Exception as e:
            if isinstance(e, InterruptedError):
                raise
            logger.warning(f"更新任务进度失败: {e}")

def cleanup_local_files(repo_path: Optional[str], output_path: Path, json_output_dir: Path):
    """
    清理本地生成的临时文件，释放存储空间。
    如果 output_path 和 json_output_dir 位于同一个 task 工作目录，则直接清理整个工作目录。
    """
    if repo_path and Path(repo_path).exists():
        try:
            repo_path_obj = Path(repo_path).expanduser().resolve()
            repo_store_root = REPO_STORE_ROOT.resolve()
            is_persistent_repo = False
            try:
                repo_path_obj.relative_to(repo_store_root)
                is_persistent_repo = True
            except ValueError:
                is_persistent_repo = False

            if is_persistent_repo:
                logger.info(f"[清理] 跳过删除持久化仓库目录: {repo_path_obj}")
            else:
                shutil.rmtree(repo_path_obj)
                logger.info(f"[清理] 已删除克隆的仓库目录: {repo_path_obj}")
        except Exception as e:
            logger.warning(f"[清理警告] 删除仓库目录失败: {repo_path}, 错误: {e}")

    # 尝试整体清理 task 工作目录（如果两者同属一个 task_dir）
    task_work_root = TASK_WORK_ROOT.resolve()
    try:
        task_dir = output_path.resolve().parent
        task_dir.relative_to(task_work_root)
        # output_path 位于 task 工作目录内，直接清理整个目录
        if task_dir.exists():
            shutil.rmtree(task_dir)
            logger.info(f"[清理] 已删除任务工作目录: {task_dir}")
        return
    except ValueError:
        pass

    # 回退：分别清理单个文件和目录
    if output_path.exists():
        try:
            output_path.unlink()
            logger.info(f"[清理] 已删除 wiki_structure.json: {output_path}")
        except Exception as e:
            logger.warning(f"[清理警告] 删除 wiki_structure.json 失败: {output_path}, 错误: {e}")

    if json_output_dir.exists():
        try:
            shutil.rmtree(json_output_dir)
            logger.info(f"[清理] 已删除 wiki_section_json 目录: {json_output_dir}")
        except Exception as e:
            logger.warning(f"[清理警告] 删除 wiki_section_json 目录失败: {json_output_dir}, 错误: {e}")

def _parse_task_result_blob(raw: Any) -> Dict[str, Any]:
    """将 Supabase tasks.result（dict 或 JSON 字符串）规范为 dict。"""
    if raw is None:
        return {}
    if isinstance(raw, dict):
        return dict(raw)
    if isinstance(raw, str):
        try:
            parsed = json.loads(raw)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}

def _strip_code_fence(text: str) -> str:
    """
    去掉 ```json``` 等代码块包裹，返回纯文本。
    """
    stripped = text.strip()
    fence_match = re.match(r"^```[\w+-]*\s*", stripped)
    if fence_match:
        stripped = stripped[fence_match.end() :]
        if stripped.endswith("```"):
            stripped = stripped[:-3]
    return stripped.strip()

def _normalize_toc_node(node: Any) -> Dict[str, Any]:
    if not isinstance(node, dict):
        raise ValueError("Invalid JSON response: toc 节点必须是对象。")

    node_id = _require_str(node, "id")
    title = _require_str(node, "title")

    normalized: Dict[str, Any] = {
        "id": node_id.strip(),
        "title": title.strip(),
    }

    children_raw = node.get("children")
    if children_raw:
        if not isinstance(children_raw, list):
            raise ValueError("Invalid JSON response: 'children' 必须是数组。")
        children = [_normalize_toc_node(child) for child in children_raw]
        if children:
            normalized["children"] = children

    files_raw = node.get("files", [])
    if files_raw:
        if not isinstance(files_raw, list):
            raise ValueError("Invalid JSON response: 'files' 必须是数组。")
        files: list[str] = []
        for item in files_raw:
            if not isinstance(item, str):
                raise ValueError("Invalid JSON response: 'files' 数组元素必须是字符串。")
            cleaned = item.strip()
            if cleaned:
                files.append(cleaned)
        normalized["files"] = files
    elif isinstance(files_raw, list):
        normalized["files"] = []

    if "files" not in normalized:
        normalized["files"] = []

    return normalized

def _require_str(obj: Dict[str, Any], key: str) -> str:
    value = obj.get(key)
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"Invalid JSON response: '{key}' 必须是非空字符串。")
    return value

class WikiSection:
    """
    表示 wiki 目录树中的一个节点，同时保存其祖先标题路径，便于提示词构造。
    """

    id: str
    title: str
    files: List[str]
    breadcrumbs: List[str] = field(default_factory=list)

    def display_path(self) -> str:
        return " / ".join(self.breadcrumbs + [self.title])

def _collect_file_context(self, files: Iterable[str]) -> str:
        """
        读取文件内容片段，并结合图谱提取依赖关系。
        """
        snippets: List[str] = []
        accumulated = 0

        rel_files = list(files)

        for rel_path in rel_files:
            if accumulated >= self.max_section_chars:
                break
            snippet = self._read_single_file(rel_path)
            if not snippet:
                continue

            # 提取图谱中的依赖信息
            dependency_info = ""
            if self.graph and rel_path in self.graph:
                deps = [neighbor for neighbor in self.graph.neighbors(rel_path) 
                        if self.graph.edges[rel_path, neighbor].get("type") == "calls"]
                if deps:
                    dependency_info = f"\n[逻辑依赖]: 该文件调用了 {', '.join(deps[:5])}"

            snippets.append(f"### {rel_path}{dependency_info}\n{snippet}")
            accumulated += len(snippet)

        return "\n\n".join(snippets)

def _parse_llm_response(self, response: str) -> Dict[str, Any]:
        """
        尝试解析模型返回的 JSON；若失败则回退为单段文本与空 Mermaid。
        """
        candidate = self._extract_json_block(response)
        if candidate:
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return data
            except json.JSONDecodeError:
                pass

        # 如果模型未遵循 JSON 要求，则将原始文本视作简介
        return {"intro": response.strip(), "sections": [], "mermaid": ""}

def _extract_json_block(text: str) -> str | None:
        """
        从模型回复中提取首个 JSON 对象字符串。
        """
        start = text.find("{")
        end = text.rfind("}")
        if start == -1 or end == -1 or end <= start:
            return None

        candidate = text[start : end + 1]
        # 简单校验括号是否匹配，避免截断
        if candidate.count("{") == candidate.count("}"):
            return candidate
        return None

def parse_supabase_timestamp(raw: Any) -> Optional[datetime]:
    """将 Supabase 返回的时间戳解析为带 UTC 时区的 datetime。"""
    if raw is None:
        return None
    if isinstance(raw, datetime):
        dt = raw
        if dt.tzinfo is None:
            return dt.replace(tzinfo=timezone.utc)
        return dt
    if isinstance(raw, str):
        s = raw.strip()
        if not s:
            return None
        try:
            if s.endswith("Z") and "+00:00" not in s and "T" in s:
                s = s[:-1] + "+00:00"
            dt = datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt
        except ValueError:
            return None
    return None

class AgentEvent:
    """
    Agent 执行过程中的事件

    事件类型：
    - 'planning': 规划阶段 {status, question, intent, entities, plan_steps}
    - 'subtask_parallel': 并行子任务 {status, subtasks_count, subtasks, elapsed_ms, results}
    - 'tool_call': 工具调用 {status, iteration, tool, operation, query, file_path, symbol_name, tools, elapsed_ms, results}
    - 'evaluation': 评估阶段 {status, iteration, is_sufficient, confidence, confidence_level, missing}
    - 'synthesis': 合成阶段 {status, answer_length, sources_count}
    - 'answer_delta': 答案增量 {delta}
    - 'complete': 完成 {answer_length, iterations, sources_count}
    - 'final_result': 最终结果 {answer, sources, trajectory, ...}
    - 'error': 错误 {error}
    """
    event_type: str
    data: Dict[str, Any]
    timestamp: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "type": self.event_type,
            "data": self.data,
            "timestamp": self.timestamp,
        }

    @staticmethod
    def create_tool_call_event(
        status: str,
        iteration: int,
        tools: List[Dict[str, Any]] = None,
        elapsed_ms: int = None,
        results: List[Dict[str, Any]] = None
    ) -> "AgentEvent":
        """创建工具调用事件"""
        data = {
            "status": status,
            "iteration": iteration,
        }

        if tools:
            # 格式化工具信息为更详细的描述
            formatted_tools = []
            for tool in tools:
                tool_name = tool.get("tool", "unknown")
                args = tool.get("arguments", {})

                formatted = {
                    "tool": tool_name,
                    "description": _get_tool_description(tool_name, args),
                }

                # 添加关键参数用于前端展示
                if tool_name == "rag_search":
                    formatted["query"] = args.get("query", "")[:100]
                elif tool_name == "code_graph":
                    formatted["operation"] = args.get("operation", "")
                    formatted["symbol_name"] = args.get("symbol_name", "")
                elif tool_name == "file_read":
                    formatted["file_path"] = args.get("file_path", "")
                elif tool_name == "repo_map":
                    formatted["include_signatures"] = args.get("include_signatures", True)
                elif tool_name == "lsp_resolve":
                    formatted["symbol_name"] = args.get("symbol_name", "")
                    formatted["operation"] = args.get("operation", "find_definition")
                    if args.get("file_hint"):
                        formatted["file_hint"] = args.get("file_hint")
                elif tool_name == "web_search":
                    formatted["query"] = args.get("query", "")[:100]
                    formatted["search_type"] = args.get("search_type", "general")
                elif tool_name == "grep_search":
                    formatted["pattern"] = args.get("pattern", "")[:100]
                    formatted["is_regex"] = args.get("is_regex", False)
                    formatted["case_sensitive"] = args.get("case_sensitive", False)

                formatted_tools.append(formatted)

            data["tools"] = formatted_tools
            data["parallel"] = len(tools) > 1

        if elapsed_ms is not None:
            data["elapsed_ms"] = elapsed_ms

        if results:
            data["results"] = results

        return AgentEvent(
            event_type="tool_call",
            data=data,
            timestamp=datetime.now().isoformat()
        )

