def to_dict(self) -> Dict[str, Any]:
        return {
            "recent_turns_count": len(self.recent_turns),
            "session_summary": self.session_summary[:200] if self.session_summary else "",
            "key_entities": self.key_entities[:10],
            "user_preferences": self.user_preferences,
        }

def to_dict(self) -> Dict[str, Any]:
        return {
            "module_responsibilities": self.module_responsibilities,
            "key_entrypoints": self.key_entrypoints,
            "core_constraints": self.core_constraints,
            "tech_stack": self.tech_stack,
            "failed_approaches": self.failed_approaches[-5:],
        }

def add_anchor(self, anchor: Anchor) -> None:
        """添加锚点"""
        self.anchors.append(anchor)
        if anchor.confidence >= 0.7:
            self.has_primary_anchor = True

def add_evidence(self, evidence: EvidenceCard) -> None:
        """添加证据卡片"""
        self.evidence_cards.append(evidence)

def add_tool_call(self, tool_call: ToolCall) -> None:
        """记录工具调用"""
        self.tool_calls_history.append(tool_call)

def _infer_evidence_type(self, piece: ContextPiece) -> EvidenceType:
        """推断证据类型

        当 RAG 命中了真实代码文件（.py/.ts 等）时，提升为 LEXICAL_MATCH 而非
        SEMANTIC_MATCH，使其能被 _hard_gate_check 的结构化证据检测识别。
        """
        source = piece.source.lower()
        if "definition" in source or "find_definition" in source:
            return EvidenceType.DEFINITION
        elif "caller" in source or "callee" in source or "call" in source:
            return EvidenceType.DIRECT_CALL
        elif "file_read" in source:
            return EvidenceType.DEFINITION
        elif "grep" in source:
            return EvidenceType.LEXICAL_MATCH
        elif "rag" in source:
            _code_exts = (
                ".py", ".pyi", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs",
                ".go", ".rs", ".java", ".kt", ".swift", ".vue", ".svelte",
            )
            sources = piece.metadata.get("sources", [])
            has_code_source = any(
                (s.split(":", 1)[-1].strip() if ":" in s else s.strip()).endswith(_code_exts)
                for s in sources
            )
            return EvidenceType.LEXICAL_MATCH if has_code_source else EvidenceType.SEMANTIC_MATCH
        elif "graph" in source:
            return EvidenceType.DIRECT_CALL
        return EvidenceType.SEMANTIC_MATCH

def _infer_confidence(self, piece: ContextPiece) -> ConfidenceLevel:
        """推断置信度"""
        if piece.relevance_score > 0.8:
            return ConfidenceLevel.CONFIRMED
        elif piece.relevance_score > 0.5:
            return ConfidenceLevel.LIKELY
        return ConfidenceLevel.UNKNOWN

def get_context_summary(self, max_length: int = 8000) -> str:
        """
        获取当前收集的上下文摘要，用于传递给 LLM。
        """
        if not self.context_scratchpad:
            return "No context has been collected yet."

        summaries = []
        total_length = 0

        for piece in sorted(self.context_scratchpad, 
                           key=lambda x: x.relevance_score, 
                           reverse=True):
            entry = f"[source: {piece.source}]"
            if piece.file_path:
                entry += f" [file: {piece.file_path}]"
            if piece.line_range:
                entry += f" [lines {piece.line_range[0]}-{piece.line_range[1]}]"
            entry += f"\n{piece.content}"

            if total_length + len(entry) > max_length:
                break

            summaries.append(entry)
            total_length += len(entry)

        return "\n\n---\n\n".join(summaries)

def get_anchors_summary(self) -> str:
        """获取锚点摘要"""
        if not self.anchors:
            return "No anchors discovered yet."

        lines = [f"Discovered {len(self.anchors)} anchor(s):"]
        for anchor in self.anchors:
            loc = f"{anchor.file_path}"
            if anchor.line_number:
                loc += f":{anchor.line_number}"
            lines.append(f"  - [{anchor.anchor_type.value}] {anchor.symbol_name} @ {loc}")
        return "\n".join(lines)

def has_verified_code_evidence(self) -> bool:
        """
        机制/调用链类问题：停止检索前至少应有 file_read、结构化证据或可靠的词法命中，
        否则仅有 RAG 语义块容易导致合成阶段「证据不足」却提前结束循环。
        """
        if any(
            tc.tool == ToolType.FILE_READ and tc.success
            for tc in self.tool_calls_history
        ):
            return True
        types_found = {e.evidence_type for e in self.evidence_cards}
        if EvidenceType.DEFINITION in types_found or EvidenceType.DIRECT_CALL in types_found:
            return True
        if EvidenceType.LEXICAL_MATCH in types_found:
            return True
        return False

def get_compressed_history(self, max_turns: int = 4) -> str:
        """
        获取压缩后的对话历史
        """
        if self.session_memory.session_summary:
            summary = f"[session summary] {self.session_memory.session_summary}\n\n"
        else:
            summary = ""

        recent = self.session_memory.recent_turns[-max_turns:] if self.session_memory.recent_turns else self.conversation_history[-max_turns:]

        if not recent:
            return summary + "No conversation history."

        parts = []
        for msg in recent:
            role = "User" if msg.get("role") == "user" else "Assistant"
            content = msg.get("content", "")
            if len(content) > 300:
                content = content[:300] + "..."
            parts.append(f"{role}: {content}")

        return summary + "\n".join(parts)

def check_stop_conditions(self) -> bool:
        """
        检查是否满足停止条件

        基于硬门控的非 LLM 判断。使用多层门控逻辑。
        区分代码类意图与文档/仓库类意图，适用不同的停止策略。
        """
        is_doc_intent = self.query_intent in DOC_CENTRIC_INTENTS
        is_soft = self.query_intent in SOFT_ANCHOR_INTENTS
        is_light = self.query_intent in LIGHT_RETRIEVAL_INTENTS

        # ========== 快速路径检查 ==========

        # 如果已经达到最大迭代次数的一半且有足够证据，可以停止
        if self.iteration_count >= self.max_iterations // 2:
            if len(self.evidence_cards) >= 3 and (self.has_primary_anchor or is_soft):
                if self.query_intent in DEEP_EXPLORATION_INTENTS:
                    if self.has_verified_code_evidence():
                        return True
                else:
                    return True

        # ========== 轻量检索意图：1 轮即够 ==========

        if is_light and self.iteration_count >= 1 and len(self.evidence_cards) >= 1:
            return True

        # ========== 文档/仓库类意图门控 ==========

        if is_doc_intent:
            # 有 2 条语义/文档证据即可停止
            doc_or_semantic = sum(
                1 for e in self.evidence_cards
                if e.evidence_type in [EvidenceType.SEMANTIC_MATCH, EvidenceType.DOCUMENTATION]
            )
            if doc_or_semantic >= 2:
                return True
            # 1 轮后有任何上下文也可停止
            if self.iteration_count >= 1 and len(self.context_scratchpad) >= 2:
                return True

        # ========== 代码类意图门控 ==========

        # 简单定位型问题：找到定义锚点即可停止
        if self.query_intent == QueryIntent.LOCATION:
            definition_anchors = [a for a in self.anchors if a.anchor_type == AnchorType.DEFINITION]
            if definition_anchors and len(self.evidence_cards) >= 1:
                return True

        # 概念型问题：有语义匹配证据即可
        if self.query_intent in [QueryIntent.CONCEPT, QueryIntent.USAGE]:
            if len(self.evidence_cards) >= 2:
                return True

        # 调用链/架构问题：需要更多证据
        if self.query_intent in [QueryIntent.CALL_CHAIN, QueryIntent.ARCHITECTURE]:
            if not self.has_closed_path and self.iteration_count < 3:
                return False
            if len(self.anchors) < 2 and self.iteration_count < 2:
                return False

        # ========== 证据充分性门控 ==========

        # 至少有一个主锚点或足够的上下文
        if not self.has_primary_anchor and not is_soft:
            if len(self.context_scratchpad) < 3 and self.iteration_count < 2:
                return False

        # 如果有冲突证据，需要继续收集（但不超过3轮）
        if self.has_conflicts and self.iteration_count < 3:
            return False

        # 证据卡片数量门控
        definition_count = sum(1 for e in self.evidence_cards if e.evidence_type == EvidenceType.DEFINITION)
        total_structural = sum(1 for e in self.evidence_cards if e.evidence_type in [EvidenceType.DEFINITION, EvidenceType.DIRECT_CALL])

        # 代码类意图：至少需要一些结构化证据，或者已经足够迭代
        if not is_soft and total_structural == 0 and definition_count == 0:
            if self.iteration_count < 2:
                return False

        # ========== 置信度门控 ==========

        # 文档类意图阈值更低
        if is_doc_intent or is_soft:
            min_confidence = 0.4 if self.iteration_count >= 1 else 0.5
        else:
            min_confidence = 0.5 if self.iteration_count >= 2 else 0.6
        if self.confidence_score < min_confidence and self.iteration_count < 3:
            return False

        # ========== 最终检查 ==========

        # 深度代码理解类：不能仅凭「多条语义片段」提前收束，否则从未 file_read / 无结构化证据
        if self.iteration_count >= 2 and len(self.evidence_cards) >= 2:
            if self.query_intent in DEEP_EXPLORATION_INTENTS:
                if self.has_verified_code_evidence():
                    return True
                if self.iteration_count >= self.max_iterations:
                    return True
                return False
            return True

        if is_light and self.iteration_count >= 1:
            return True

        return False

class CodeGraphTool:
    """
    代码知识图谱查询工具

    封装对 NetworkX 图谱的查询操作，提供结构化的代码关系查询能力。
    """

    OPERATIONS = Literal[
        "find_definition",
        "find_callers", 
        "find_callees",
        "get_class_hierarchy",
        "get_file_symbols",
        "get_all_symbols",
        "find_imports",
        "get_module_dependencies"
    ]

    # 关系类型标签
    RELATION_LABELS = {
        "calls": "calls",
        "contains": "contains",
        "inherits": "inherits",
        "imports": "imports",
        "references": "references",
        "implements": "implements",
    }

    # 这些 operation 在「零命中」时应显著降分；get_all_symbols 等概览除外
    _OPS_SENSITIVE_TO_EMPTY_HITS = frozenset({
        "find_definition",
        "find_callers",
        "find_callees",
        "get_class_hierarchy",
        "get_file_symbols",
        "find_imports",
        "get_module_dependencies",
    })

    def __init__(self, graph_path: Optional[str] = None):
        self.graph: nx.DiGraph = nx.DiGraph()
        self.graph_path = graph_path

        if graph_path and Path(graph_path).exists():
            self._load_graph(graph_path)

    def _load_graph(self, path: str) -> None:
        """加载图谱"""
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            self.graph = nx.node_link_graph(data)
            logger.info(f"Loaded code graph with {self.graph.number_of_nodes()} nodes and {self.graph.number_of_edges()} edges")
        except Exception as e:
            logger.error(f"Failed to load graph from {path}: {e}")
            self.graph = nx.DiGraph()

    def execute(
        self,
        operation: str,
        symbol_name: Optional[str] = None,
        file_path: Optional[str] = None,
        **kwargs
    ) -> ContextPiece:
        """
        执行图谱查询操作

        返回结构化的 ContextPiece，包含：
        - 查询结果内容
        - 关系标签
        - 用于锚点提取的元数据
        """
        try:
            if operation == "find_definition":
                result, metadata = self._find_definition(symbol_name, file_path)
            elif operation == "find_callers":
                result, metadata = self._find_callers(symbol_name, file_path)
            elif operation == "find_callees":
                result, metadata = self._find_callees(symbol_name, file_path)
            elif operation == "get_class_hierarchy":
                result, metadata = self._get_class_hierarchy(symbol_name)
            elif operation == "get_file_symbols":
                result, metadata = self._get_file_symbols(file_path)
            elif operation == "get_all_symbols":
                result, metadata = self._get_all_symbols()
            elif operation == "find_imports":
                result, metadata = self._find_imports(file_path)
            elif operation == "get_module_dependencies":
                result, metadata = self._get_module_dependencies(file_path or symbol_name)
            else:
                result = f"Unknown operation: {operation}"
                metadata = {"error": "unknown_operation"}

            # 计算相关性分数
            relevance = self._compute_relevance(operation, metadata)

            return ContextPiece(
                source=f"code_graph.{operation}",
                content=result,
                file_path=metadata.get("primary_file"),
                line_range=metadata.get("line_range"),
                relevance_score=relevance,
                metadata={
                    "operation": operation,
                    "symbol_name": symbol_name,
                    "file_path": file_path,
                    "relation_type": metadata.get("relation_type"),
                    "symbols_found": metadata.get("symbols_found", []),
                    "anchor_candidates": metadata.get("anchor_candidates", []),
                }
            )

        except Exception as e:
            logger.error(f"Graph query failed: {e}")
            return ContextPiece(
                source=f"code_graph.{operation}",
                content=f"Query failed: {str(e)}",
                relevance_score=0.0,
                metadata={"error": str(e)}
            )

    def _compute_relevance(self, operation: str, metadata: Dict[str, Any]) -> float:
        """计算结果的相关性分数"""
        base_scores = {
            "find_definition": 0.9,
            "find_callers": 0.85,
            "find_callees": 0.85,
            "get_class_hierarchy": 0.8,
            "get_file_symbols": 0.75,
            "get_all_symbols": 0.7,
            "find_imports": 0.75,
            "get_module_dependencies": 0.75,
        }

        score = base_scores.get(operation, 0.7)

        # 找到结果则提高分数
        if metadata.get("symbols_found"):
            score = min(1.0, score + 0.05)

        # 有错误则降低分数
        if metadata.get("error"):
            score = 0.0

        # 查询类操作若无命中，不应保持高 base 分（否则评估器误判「已成功检索」）
        symbols = metadata.get("symbols_found")
        if (
            operation in self._OPS_SENSITIVE_TO_EMPTY_HITS
            and score > 0
            and isinstance(symbols, list)
            and len(symbols) == 0
        ):
            score = min(score, 0.12)

        return score

    def _find_definition(self, symbol_name: str, file_path: Optional[str] = None) -> Tuple[str, Dict[str, Any]]:
        """查找符号定义位置"""
        if not symbol_name:
            return "Error: symbol_name is required", {"error": "missing_symbol"}

        matches = []
        for node_id, data in self.graph.nodes(data=True):
            node_name = data.get("name", "")
            node_type = data.get("type", "")
            node_file = data.get("file", "")

            if node_name == symbol_name or node_id.endswith(f":{symbol_name}"):
                if file_path and file_path not in node_file:
                    continue
                matches.append({
                    "node_id": node_id,
                    "type": node_type,
                    "file": node_file,
                    "name": node_name,
                    "line": data.get("line"),
                })

        if not matches:
            return f"No definition found for symbol: {symbol_name}", {"symbols_found": []}

        result_lines = [f"Found {len(matches)} definition(s) for '{symbol_name}':"]
        result_lines.append("")

        anchor_candidates = []
        for match in matches:
            result_lines.append(f"  [{match['type']}] {match['node_id']}")
            result_lines.append(f"    📁 File: {match['file']}")
            if match.get('line'):
                result_lines.append(f"    📍 Line: {match['line']}")
            result_lines.append("")

            anchor_candidates.append({
                "anchor_type": "definition",
                "symbol_name": match['name'],
                "file_path": match['file'],
                "line_number": match.get('line'),
            })

        metadata = {
            "relation_type": "definition",
            "symbols_found": [m['name'] for m in matches],
            "primary_file": matches[0]['file'] if matches else None,
            "anchor_candidates": anchor_candidates,
        }

        return "\n".join(result_lines), metadata

    def _find_callers(self, symbol_name: str, file_path: Optional[str] = None) -> Tuple[str, Dict[str, Any]]:
        """查找调用某符号的位置"""
        if not symbol_name:
            return "Error: symbol_name is required", {"error": "missing_symbol"}

        target_nodes = [
            node_id for node_id, data in self.graph.nodes(data=True)
            if data.get("name") == symbol_name or node_id.endswith(f":{symbol_name}")
        ]

        if not target_nodes:
            return f"Symbol not found in graph: {symbol_name}", {"symbols_found": []}

        callers = []
        for target in target_nodes:
            for pred in self.graph.predecessors(target):
                edge_data = self.graph.get_edge_data(pred, target)
                if edge_data and edge_data.get("type") == "calls":
                    pred_data = self.graph.nodes[pred]
                    if file_path and file_path not in pred_data.get("file", ""):
                        continue
                    callers.append({
                        "caller": pred,
                        "caller_name": pred_data.get("name", pred),
                        "file": pred_data.get("file", "unknown"),
                        "type": pred_data.get("type", "unknown"),
                        "line": pred_data.get("line"),
                    })

        if not callers:
            return f"No callers found for: {symbol_name}", {"relation_type": "calls", "symbols_found": []}

        result_lines = [f"Found {len(callers)} caller(s) of '{symbol_name}':"]
        result_lines.append("")

        for caller in callers:
            result_lines.append(f"  [{caller['type']}] {caller['caller_name']}")
            result_lines.append(f"    📁 File: {caller['file']}")
            result_lines.append(f"    → calls → {symbol_name}")
            result_lines.append("")

        metadata = {
            "relation_type": "calls",
            "symbols_found": [c['caller_name'] for c in callers],
            "primary_file": callers[0]['file'] if callers else None,
            "anchor_candidates": [
                {
                    "anchor_type": "reference",
                    "symbol_name": c['caller_name'],
                    "file_path": c['file'],
                    "line_number": c.get('line'),
                }
                for c in callers[:5]
            ],
        }

        return "\n".join(result_lines), metadata

    def _find_callees(self, symbol_name: str, file_path: Optional[str] = None) -> Tuple[str, Dict[str, Any]]:
        """查找某符号调用的其他符号"""
        if not symbol_name:
            return "Error: symbol_name is required", {"error": "missing_symbol"}

        source_nodes = [
            node_id for node_id, data in self.graph.nodes(data=True)
            if data.get("name") == symbol_name or node_id.endswith(f":{symbol_name}")
        ]

        if not source_nodes:
            return f"Symbol not found in graph: {symbol_name}", {"symbols_found": []}

        callees = []
        for source in source_nodes:
            source_data = self.graph.nodes[source]
            for succ in self.graph.successors(source):
                edge_data = self.graph.get_edge_data(source, succ)
                if edge_data and edge_data.get("type") == "calls":
                    succ_data = self.graph.nodes[succ]
                    callees.append({
                        "callee": succ,
                        "callee_name": succ_data.get("name", succ),
                        "file": succ_data.get("file", "unknown"),
                        "type": succ_data.get("type", "unknown"),
                        "line": succ_data.get("line"),
                        "source_file": source_data.get("file", "unknown"),
                    })

        if not callees:
            return f"No callees found for: {symbol_name}", {"relation_type": "calls", "symbols_found": []}

        result_lines = [f"'{symbol_name}' calls {len(callees)} function(s):"]
        result_lines.append("")

        for callee in callees:
            result_lines.append(f"  {symbol_name} → calls → [{callee['type']}] {callee['callee_name']}")
            result_lines.append(f"    📁 Defined in: {callee['file']}")
            result_lines.append("")

        metadata = {
            "relation_type": "calls",
            "symbols_found": [c['callee_name'] for c in callees],
            "primary_file": callees[0]['source_file'] if callees else None,
            "anchor_candidates": [
                {
                    "anchor_type": "reference",
                    "symbol_name": c['callee_name'],
                    "file_path": c['file'],
                    "line_number": c.get('line'),
                }
                for c in callees[:5]
            ],
        }

        return "\n".join(result_lines), metadata

    def _get_class_hierarchy(self, class_name: str) -> Tuple[str, Dict[str, Any]]:
        """获取类的继承层次"""
        if not class_name:
            return "Error: class_name is required", {"error": "missing_symbol"}

        class_nodes = [
            (node_id, data) for node_id, data in self.graph.nodes(data=True)
            if data.get("type") == "class" and 
            (data.get("name") == class_name or node_id.endswith(f":{class_name}"))
        ]

        if not class_nodes:
            return f"Class not found: {class_name}", {"symbols_found": []}

        result_lines = [f"Class hierarchy for '{class_name}':"]
        result_lines.append("")

        symbols_found = []
        anchor_candidates = []

        for node_id, data in class_nodes:
            result_lines.append(f"📦 Class: {data.get('name', node_id)}")
            result_lines.append(f"  📁 File: {data.get('file', 'unknown')}")

            symbols_found.append(data.get('name', node_id))
            anchor_candidates.append({
                "anchor_type": "definition",
                "symbol_name": data.get('name', node_id),
                "file_path": data.get('file', 'unknown'),
            })

            # 父类
            parents = []
            for pred in self.graph.predecessors(node_id):
                edge_data = self.graph.get_edge_data(pred, node_id)
                if edge_data and edge_data.get("type") == "inherits":
                    pred_data = self.graph.nodes[pred]
                    parents.append({
                        "name": pred_data.get("name", pred),
                        "file": pred_data.get("file", "unknown"),
                    })

            if parents:
                result_lines.append(f"  ⬆️ Extends:")
                for p in parents:
                    result_lines.append(f"    - {p['name']} ({p['file']})")

            # 子类
            children = []
            for succ in self.graph.successors(node_id):
                edge_data = self.graph.get_edge_data(node_id, succ)
                if edge_data and edge_data.get("type") == "inherits":
                    succ_data = self.graph.nodes[succ]
                    children.append({
                        "name": succ_data.get("name", succ),
                        "file": succ_data.get("file", "unknown"),
                    })

            if children:
                result_lines.append(f"  ⬇️ Subclasses:")
                for c in children:
                    result_lines.append(f"    - {c['name']} ({c['file']})")

            # 方法
            methods = []
            for succ in self.graph.successors(node_id):
                edge_data = self.graph.get_edge_data(node_id, succ)
                if edge_data and edge_data.get("type") == "contains":
                    succ_data = self.graph.nodes[succ]
                    if succ_data.get("type") == "function":
                        methods.append(succ_data.get("name", succ))

            if methods:
                result_lines.append(f"  🔧 Methods: {', '.join(methods[:10])}")
                if len(methods) > 10:
                    result_lines.append(f"      ... and {len(methods) - 10} more")

            result_lines.append("")

        metadata = {
            "relation_type": "inherits",
            "symbols_found": symbols_found,
            "primary_file": class_nodes[0][1].get('file') if class_nodes else None,
            "anchor_candidates": anchor_candidates,
        }

        return "\n".join(result_lines), metadata

    def _get_file_symbols(self, file_path: str) -> Tuple[str, Dict[str, Any]]:
        """获取文件中定义的所有符号"""
        if not file_path:
            return "Error: file_path is required", {"error": "missing_file_path"}

        symbols = []
        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if file_path in node_file or node_file.endswith(file_path):
                symbols.append({
                    "name": data.get("name", node_id),
                    "type": data.get("type", "unknown"),
                    "node_id": node_id,
                    "line": data.get("line"),
                })

        if not symbols:
            return f"No symbols found in file: {file_path}", {"symbols_found": []}

        classes = [s for s in symbols if s["type"] == "class"]
        functions = [s for s in symbols if s["type"] == "function"]
        others = [s for s in symbols if s["type"] not in ("class", "function", "file")]

        result_lines = [f"Symbols in '{file_path}':"]
        result_lines.append("")

        if classes:
            result_lines.append(f"📦 Classes ({len(classes)}):")
            for c in classes:
                line_info = f" [line {c['line']}]" if c.get('line') else ""
                result_lines.append(f"  - {c['name']}{line_info}")

        if functions:
            result_lines.append(f"\n🔧 Functions ({len(functions)}):")
            for f in functions[:20]:
                line_info = f" [line {f['line']}]" if f.get('line') else ""
                result_lines.append(f"  - {f['name']}{line_info}")
            if len(functions) > 20:
                result_lines.append(f"  ... and {len(functions) - 20} more")

        if others:
            result_lines.append(f"\n📋 Other ({len(others)}):")
            for o in others[:10]:
                result_lines.append(f"  - [{o['type']}] {o['name']}")

        metadata = {
            "relation_type": "contains",
            "symbols_found": [s['name'] for s in symbols],
            "primary_file": file_path,
            "anchor_candidates": [
                {
                    "anchor_type": "definition",
                    "symbol_name": s['name'],
                    "file_path": file_path,
                    "line_number": s.get('line'),
                }
                for s in (classes + functions)[:10]
            ],
        }

        return "\n".join(result_lines), metadata

    def _get_all_symbols(self, limit: int = 50) -> Tuple[str, Dict[str, Any]]:
        """获取图谱中所有主要符号的概览"""
        classes = []
        functions = []
        files = []

        for node_id, data in self.graph.nodes(data=True):
            node_type = data.get("type", "")
            if node_type == "class":
                classes.append({
                    "name": data.get("name", node_id),
                    "file": data.get("file", "unknown"),
                })
            elif node_type == "function":
                functions.append({
                    "name": data.get("name", node_id),
                    "file": data.get("file", "unknown"),
                })
            elif node_type == "file":
                files.append(node_id)

        result_lines = [
            "📊 Code Graph Overview:",
            f"  Total nodes: {self.graph.number_of_nodes()}",
            f"  Total edges: {self.graph.number_of_edges()}",
            f"  Files: {len(files)}",
            f"  Classes: {len(classes)}",
            f"  Functions: {len(functions)}",
            "",
        ]

        if classes:
            result_lines.append("📦 Key Classes:")
            for c in classes[:15]:
                result_lines.append(f"  - {c['name']} ({c['file']})")
            if len(classes) > 15:
                result_lines.append(f"  ... and {len(classes) - 15} more")

        if functions:
            result_lines.append("\n🔧 Key Functions:")
            for f in functions[:15]:
                result_lines.append(f"  - {f['name']} ({f['file']})")
            if len(functions) > 15:
                result_lines.append(f"  ... and {len(functions) - 15} more")

        metadata = {
            "relation_type": "overview",
            "symbols_found": [c['name'] for c in classes[:10]] + [f['name'] for f in functions[:10]],
            "anchor_candidates": [],
        }

        return "\n".join(result_lines), metadata

    def _find_imports(self, file_path: str) -> Tuple[str, Dict[str, Any]]:
        """查找文件的导入关系"""
        if not file_path:
            return "Error: file_path is required", {"error": "missing_file_path"}

        imports = []
        imported_by = []

        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if file_path in node_file or node_file.endswith(file_path):
                # 该文件导入的
                for succ in self.graph.successors(node_id):
                    edge_data = self.graph.get_edge_data(node_id, succ)
                    if edge_data and edge_data.get("type") == "imports":
                        succ_data = self.graph.nodes[succ]
                        imports.append({
                            "name": succ_data.get("name", succ),
                            "file": succ_data.get("file", "unknown"),
                        })

                # 被其他文件导入的
                for pred in self.graph.predecessors(node_id):
                    edge_data = self.graph.get_edge_data(pred, node_id)
                    if edge_data and edge_data.get("type") == "imports":
                        pred_data = self.graph.nodes[pred]
                        imported_by.append({
                            "name": pred_data.get("name", pred),
                            "file": pred_data.get("file", "unknown"),
                        })

        result_lines = [f"Import relationships for '{file_path}':"]
        result_lines.append("")

        if imports:
            result_lines.append("⬇️ Imports:")
            for imp in imports[:20]:
                result_lines.append(f"  - {imp['name']} from {imp['file']}")

        if imported_by:
            result_lines.append("\n⬆️ Imported by:")
            for imp in imported_by[:20]:
                result_lines.append(f"  - {imp['name']} in {imp['file']}")

        if not imports and not imported_by:
            result_lines.append("No import relationships found.")

        metadata = {
            "relation_type": "imports",
            "symbols_found": [i['name'] for i in imports + imported_by],
            "primary_file": file_path,
        }

        return "\n".join(result_lines), metadata

    def _get_module_dependencies(self, module_path: str) -> Tuple[str, Dict[str, Any]]:
        """获取模块级依赖关系"""
        if not module_path:
            return "Error: module_path is required", {"error": "missing_module_path"}

        # 找到模块内的所有文件
        module_files = []
        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if module_path in node_file:
                module_files.append(node_file)

        module_files = list(set(module_files))

        # 找出依赖
        external_deps = set()
        internal_deps = set()

        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if module_path not in node_file:
                continue

            for succ in self.graph.successors(node_id):
                edge_data = self.graph.get_edge_data(node_id, succ)
                if edge_data and edge_data.get("type") in ["imports", "calls"]:
                    succ_data = self.graph.nodes[succ]
                    succ_file = succ_data.get("file", "")

                    if module_path in succ_file:
                        internal_deps.add(succ_file)
                    elif succ_file:
                        external_deps.add(succ_file)

        result_lines = [f"Module dependencies for '{module_path}':"]
        result_lines.append(f"  Files in module: {len(module_files)}")
        result_lines.append("")

        if internal_deps:
            result_lines.append("🔄 Internal dependencies:")
            for dep in sorted(internal_deps)[:15]:
                result_lines.append(f"  - {dep}")

        if external_deps:
            result_lines.append("\n📦 External dependencies:")
            for dep in sorted(external_deps)[:15]:
                result_lines.append(f"  - {dep}")

        metadata = {
            "relation_type": "module_dependency",
            "symbols_found": list(internal_deps | external_deps)[:20],
            "primary_file": module_path,
        }

        return "\n".join(result_lines), metadata

    def is_loaded(self) -> bool:
        """检查图谱是否已加载"""
        return self.graph.number_of_nodes() > 0

def __init__(self, graph_path: Optional[str] = None):
        self.graph: nx.DiGraph = nx.DiGraph()
        self.graph_path = graph_path

        if graph_path and Path(graph_path).exists():
            self._load_graph(graph_path)

def _load_graph(self, path: str) -> None:
        """加载图谱"""
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            self.graph = nx.node_link_graph(data)
            logger.info(f"Loaded code graph with {self.graph.number_of_nodes()} nodes and {self.graph.number_of_edges()} edges")
        except Exception as e:
            logger.error(f"Failed to load graph from {path}: {e}")
            self.graph = nx.DiGraph()

def execute(
        self,
        operation: str,
        symbol_name: Optional[str] = None,
        file_path: Optional[str] = None,
        **kwargs
    ) -> ContextPiece:
        """
        执行图谱查询操作

        返回结构化的 ContextPiece，包含：
        - 查询结果内容
        - 关系标签
        - 用于锚点提取的元数据
        """
        try:
            if operation == "find_definition":
                result, metadata = self._find_definition(symbol_name, file_path)
            elif operation == "find_callers":
                result, metadata = self._find_callers(symbol_name, file_path)
            elif operation == "find_callees":
                result, metadata = self._find_callees(symbol_name, file_path)
            elif operation == "get_class_hierarchy":
                result, metadata = self._get_class_hierarchy(symbol_name)
            elif operation == "get_file_symbols":
                result, metadata = self._get_file_symbols(file_path)
            elif operation == "get_all_symbols":
                result, metadata = self._get_all_symbols()
            elif operation == "find_imports":
                result, metadata = self._find_imports(file_path)
            elif operation == "get_module_dependencies":
                result, metadata = self._get_module_dependencies(file_path or symbol_name)
            else:
                result = f"Unknown operation: {operation}"
                metadata = {"error": "unknown_operation"}

            # 计算相关性分数
            relevance = self._compute_relevance(operation, metadata)

            return ContextPiece(
                source=f"code_graph.{operation}",
                content=result,
                file_path=metadata.get("primary_file"),
                line_range=metadata.get("line_range"),
                relevance_score=relevance,
                metadata={
                    "operation": operation,
                    "symbol_name": symbol_name,
                    "file_path": file_path,
                    "relation_type": metadata.get("relation_type"),
                    "symbols_found": metadata.get("symbols_found", []),
                    "anchor_candidates": metadata.get("anchor_candidates", []),
                }
            )

        except Exception as e:
            logger.error(f"Graph query failed: {e}")
            return ContextPiece(
                source=f"code_graph.{operation}",
                content=f"Query failed: {str(e)}",
                relevance_score=0.0,
                metadata={"error": str(e)}
            )

def _find_definition(self, symbol_name: str, file_path: Optional[str] = None) -> Tuple[str, Dict[str, Any]]:
        """查找符号定义位置"""
        if not symbol_name:
            return "Error: symbol_name is required", {"error": "missing_symbol"}

        matches = []
        for node_id, data in self.graph.nodes(data=True):
            node_name = data.get("name", "")
            node_type = data.get("type", "")
            node_file = data.get("file", "")

            if node_name == symbol_name or node_id.endswith(f":{symbol_name}"):
                if file_path and file_path not in node_file:
                    continue
                matches.append({
                    "node_id": node_id,
                    "type": node_type,
                    "file": node_file,
                    "name": node_name,
                    "line": data.get("line"),
                })

        if not matches:
            return f"No definition found for symbol: {symbol_name}", {"symbols_found": []}

        result_lines = [f"Found {len(matches)} definition(s) for '{symbol_name}':"]
        result_lines.append("")

        anchor_candidates = []
        for match in matches:
            result_lines.append(f"  [{match['type']}] {match['node_id']}")
            result_lines.append(f"    📁 File: {match['file']}")
            if match.get('line'):
                result_lines.append(f"    📍 Line: {match['line']}")
            result_lines.append("")

            anchor_candidates.append({
                "anchor_type": "definition",
                "symbol_name": match['name'],
                "file_path": match['file'],
                "line_number": match.get('line'),
            })

        metadata = {
            "relation_type": "definition",
            "symbols_found": [m['name'] for m in matches],
            "primary_file": matches[0]['file'] if matches else None,
            "anchor_candidates": anchor_candidates,
        }

        return "\n".join(result_lines), metadata

def _find_callers(self, symbol_name: str, file_path: Optional[str] = None) -> Tuple[str, Dict[str, Any]]:
        """查找调用某符号的位置"""
        if not symbol_name:
            return "Error: symbol_name is required", {"error": "missing_symbol"}

        target_nodes = [
            node_id for node_id, data in self.graph.nodes(data=True)
            if data.get("name") == symbol_name or node_id.endswith(f":{symbol_name}")
        ]

        if not target_nodes:
            return f"Symbol not found in graph: {symbol_name}", {"symbols_found": []}

        callers = []
        for target in target_nodes:
            for pred in self.graph.predecessors(target):
                edge_data = self.graph.get_edge_data(pred, target)
                if edge_data and edge_data.get("type") == "calls":
                    pred_data = self.graph.nodes[pred]
                    if file_path and file_path not in pred_data.get("file", ""):
                        continue
                    callers.append({
                        "caller": pred,
                        "caller_name": pred_data.get("name", pred),
                        "file": pred_data.get("file", "unknown"),
                        "type": pred_data.get("type", "unknown"),
                        "line": pred_data.get("line"),
                    })

        if not callers:
            return f"No callers found for: {symbol_name}", {"relation_type": "calls", "symbols_found": []}

        result_lines = [f"Found {len(callers)} caller(s) of '{symbol_name}':"]
        result_lines.append("")

        for caller in callers:
            result_lines.append(f"  [{caller['type']}] {caller['caller_name']}")
            result_lines.append(f"    📁 File: {caller['file']}")
            result_lines.append(f"    → calls → {symbol_name}")
            result_lines.append("")

        metadata = {
            "relation_type": "calls",
            "symbols_found": [c['caller_name'] for c in callers],
            "primary_file": callers[0]['file'] if callers else None,
            "anchor_candidates": [
                {
                    "anchor_type": "reference",
                    "symbol_name": c['caller_name'],
                    "file_path": c['file'],
                    "line_number": c.get('line'),
                }
                for c in callers[:5]
            ],
        }

        return "\n".join(result_lines), metadata

def _find_callees(self, symbol_name: str, file_path: Optional[str] = None) -> Tuple[str, Dict[str, Any]]:
        """查找某符号调用的其他符号"""
        if not symbol_name:
            return "Error: symbol_name is required", {"error": "missing_symbol"}

        source_nodes = [
            node_id for node_id, data in self.graph.nodes(data=True)
            if data.get("name") == symbol_name or node_id.endswith(f":{symbol_name}")
        ]

        if not source_nodes:
            return f"Symbol not found in graph: {symbol_name}", {"symbols_found": []}

        callees = []
        for source in source_nodes:
            source_data = self.graph.nodes[source]
            for succ in self.graph.successors(source):
                edge_data = self.graph.get_edge_data(source, succ)
                if edge_data and edge_data.get("type") == "calls":
                    succ_data = self.graph.nodes[succ]
                    callees.append({
                        "callee": succ,
                        "callee_name": succ_data.get("name", succ),
                        "file": succ_data.get("file", "unknown"),
                        "type": succ_data.get("type", "unknown"),
                        "line": succ_data.get("line"),
                        "source_file": source_data.get("file", "unknown"),
                    })

        if not callees:
            return f"No callees found for: {symbol_name}", {"relation_type": "calls", "symbols_found": []}

        result_lines = [f"'{symbol_name}' calls {len(callees)} function(s):"]
        result_lines.append("")

        for callee in callees:
            result_lines.append(f"  {symbol_name} → calls → [{callee['type']}] {callee['callee_name']}")
            result_lines.append(f"    📁 Defined in: {callee['file']}")
            result_lines.append("")

        metadata = {
            "relation_type": "calls",
            "symbols_found": [c['callee_name'] for c in callees],
            "primary_file": callees[0]['source_file'] if callees else None,
            "anchor_candidates": [
                {
                    "anchor_type": "reference",
                    "symbol_name": c['callee_name'],
                    "file_path": c['file'],
                    "line_number": c.get('line'),
                }
                for c in callees[:5]
            ],
        }

        return "\n".join(result_lines), metadata

def _get_class_hierarchy(self, class_name: str) -> Tuple[str, Dict[str, Any]]:
        """获取类的继承层次"""
        if not class_name:
            return "Error: class_name is required", {"error": "missing_symbol"}

        class_nodes = [
            (node_id, data) for node_id, data in self.graph.nodes(data=True)
            if data.get("type") == "class" and 
            (data.get("name") == class_name or node_id.endswith(f":{class_name}"))
        ]

        if not class_nodes:
            return f"Class not found: {class_name}", {"symbols_found": []}

        result_lines = [f"Class hierarchy for '{class_name}':"]
        result_lines.append("")

        symbols_found = []
        anchor_candidates = []

        for node_id, data in class_nodes:
            result_lines.append(f"📦 Class: {data.get('name', node_id)}")
            result_lines.append(f"  📁 File: {data.get('file', 'unknown')}")

            symbols_found.append(data.get('name', node_id))
            anchor_candidates.append({
                "anchor_type": "definition",
                "symbol_name": data.get('name', node_id),
                "file_path": data.get('file', 'unknown'),
            })

            # 父类
            parents = []
            for pred in self.graph.predecessors(node_id):
                edge_data = self.graph.get_edge_data(pred, node_id)
                if edge_data and edge_data.get("type") == "inherits":
                    pred_data = self.graph.nodes[pred]
                    parents.append({
                        "name": pred_data.get("name", pred),
                        "file": pred_data.get("file", "unknown"),
                    })

            if parents:
                result_lines.append(f"  ⬆️ Extends:")
                for p in parents:
                    result_lines.append(f"    - {p['name']} ({p['file']})")

            # 子类
            children = []
            for succ in self.graph.successors(node_id):
                edge_data = self.graph.get_edge_data(node_id, succ)
                if edge_data and edge_data.get("type") == "inherits":
                    succ_data = self.graph.nodes[succ]
                    children.append({
                        "name": succ_data.get("name", succ),
                        "file": succ_data.get("file", "unknown"),
                    })

            if children:
                result_lines.append(f"  ⬇️ Subclasses:")
                for c in children:
                    result_lines.append(f"    - {c['name']} ({c['file']})")

            # 方法
            methods = []
            for succ in self.graph.successors(node_id):
                edge_data = self.graph.get_edge_data(node_id, succ)
                if edge_data and edge_data.get("type") == "contains":
                    succ_data = self.graph.nodes[succ]
                    if succ_data.get("type") == "function":
                        methods.append(succ_data.get("name", succ))

            if methods:
                result_lines.append(f"  🔧 Methods: {', '.join(methods[:10])}")
                if len(methods) > 10:
                    result_lines.append(f"      ... and {len(methods) - 10} more")

            result_lines.append("")

        metadata = {
            "relation_type": "inherits",
            "symbols_found": symbols_found,
            "primary_file": class_nodes[0][1].get('file') if class_nodes else None,
            "anchor_candidates": anchor_candidates,
        }

        return "\n".join(result_lines), metadata

def _get_file_symbols(self, file_path: str) -> Tuple[str, Dict[str, Any]]:
        """获取文件中定义的所有符号"""
        if not file_path:
            return "Error: file_path is required", {"error": "missing_file_path"}

        symbols = []
        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if file_path in node_file or node_file.endswith(file_path):
                symbols.append({
                    "name": data.get("name", node_id),
                    "type": data.get("type", "unknown"),
                    "node_id": node_id,
                    "line": data.get("line"),
                })

        if not symbols:
            return f"No symbols found in file: {file_path}", {"symbols_found": []}

        classes = [s for s in symbols if s["type"] == "class"]
        functions = [s for s in symbols if s["type"] == "function"]
        others = [s for s in symbols if s["type"] not in ("class", "function", "file")]

        result_lines = [f"Symbols in '{file_path}':"]
        result_lines.append("")

        if classes:
            result_lines.append(f"📦 Classes ({len(classes)}):")
            for c in classes:
                line_info = f" [line {c['line']}]" if c.get('line') else ""
                result_lines.append(f"  - {c['name']}{line_info}")

        if functions:
            result_lines.append(f"\n🔧 Functions ({len(functions)}):")
            for f in functions[:20]:
                line_info = f" [line {f['line']}]" if f.get('line') else ""
                result_lines.append(f"  - {f['name']}{line_info}")
            if len(functions) > 20:
                result_lines.append(f"  ... and {len(functions) - 20} more")

        if others:
            result_lines.append(f"\n📋 Other ({len(others)}):")
            for o in others[:10]:
                result_lines.append(f"  - [{o['type']}] {o['name']}")

        metadata = {
            "relation_type": "contains",
            "symbols_found": [s['name'] for s in symbols],
            "primary_file": file_path,
            "anchor_candidates": [
                {
                    "anchor_type": "definition",
                    "symbol_name": s['name'],
                    "file_path": file_path,
                    "line_number": s.get('line'),
                }
                for s in (classes + functions)[:10]
            ],
        }

        return "\n".join(result_lines), metadata

def _get_all_symbols(self, limit: int = 50) -> Tuple[str, Dict[str, Any]]:
        """获取图谱中所有主要符号的概览"""
        classes = []
        functions = []
        files = []

        for node_id, data in self.graph.nodes(data=True):
            node_type = data.get("type", "")
            if node_type == "class":
                classes.append({
                    "name": data.get("name", node_id),
                    "file": data.get("file", "unknown"),
                })
            elif node_type == "function":
                functions.append({
                    "name": data.get("name", node_id),
                    "file": data.get("file", "unknown"),
                })
            elif node_type == "file":
                files.append(node_id)

        result_lines = [
            "📊 Code Graph Overview:",
            f"  Total nodes: {self.graph.number_of_nodes()}",
            f"  Total edges: {self.graph.number_of_edges()}",
            f"  Files: {len(files)}",
            f"  Classes: {len(classes)}",
            f"  Functions: {len(functions)}",
            "",
        ]

        if classes:
            result_lines.append("📦 Key Classes:")
            for c in classes[:15]:
                result_lines.append(f"  - {c['name']} ({c['file']})")
            if len(classes) > 15:
                result_lines.append(f"  ... and {len(classes) - 15} more")

        if functions:
            result_lines.append("\n🔧 Key Functions:")
            for f in functions[:15]:
                result_lines.append(f"  - {f['name']} ({f['file']})")
            if len(functions) > 15:
                result_lines.append(f"  ... and {len(functions) - 15} more")

        metadata = {
            "relation_type": "overview",
            "symbols_found": [c['name'] for c in classes[:10]] + [f['name'] for f in functions[:10]],
            "anchor_candidates": [],
        }

        return "\n".join(result_lines), metadata

def _find_imports(self, file_path: str) -> Tuple[str, Dict[str, Any]]:
        """查找文件的导入关系"""
        if not file_path:
            return "Error: file_path is required", {"error": "missing_file_path"}

        imports = []
        imported_by = []

        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if file_path in node_file or node_file.endswith(file_path):
                # 该文件导入的
                for succ in self.graph.successors(node_id):
                    edge_data = self.graph.get_edge_data(node_id, succ)
                    if edge_data and edge_data.get("type") == "imports":
                        succ_data = self.graph.nodes[succ]
                        imports.append({
                            "name": succ_data.get("name", succ),
                            "file": succ_data.get("file", "unknown"),
                        })

                # 被其他文件导入的
                for pred in self.graph.predecessors(node_id):
                    edge_data = self.graph.get_edge_data(pred, node_id)
                    if edge_data and edge_data.get("type") == "imports":
                        pred_data = self.graph.nodes[pred]
                        imported_by.append({
                            "name": pred_data.get("name", pred),
                            "file": pred_data.get("file", "unknown"),
                        })

        result_lines = [f"Import relationships for '{file_path}':"]
        result_lines.append("")

        if imports:
            result_lines.append("⬇️ Imports:")
            for imp in imports[:20]:
                result_lines.append(f"  - {imp['name']} from {imp['file']}")

        if imported_by:
            result_lines.append("\n⬆️ Imported by:")
            for imp in imported_by[:20]:
                result_lines.append(f"  - {imp['name']} in {imp['file']}")

        if not imports and not imported_by:
            result_lines.append("No import relationships found.")

        metadata = {
            "relation_type": "imports",
            "symbols_found": [i['name'] for i in imports + imported_by],
            "primary_file": file_path,
        }

        return "\n".join(result_lines), metadata

def _get_module_dependencies(self, module_path: str) -> Tuple[str, Dict[str, Any]]:
        """获取模块级依赖关系"""
        if not module_path:
            return "Error: module_path is required", {"error": "missing_module_path"}

        # 找到模块内的所有文件
        module_files = []
        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if module_path in node_file:
                module_files.append(node_file)

        module_files = list(set(module_files))

        # 找出依赖
        external_deps = set()
        internal_deps = set()

        for node_id, data in self.graph.nodes(data=True):
            node_file = data.get("file", "")
            if module_path not in node_file:
                continue

            for succ in self.graph.successors(node_id):
                edge_data = self.graph.get_edge_data(node_id, succ)
                if edge_data and edge_data.get("type") in ["imports", "calls"]:
                    succ_data = self.graph.nodes[succ]
                    succ_file = succ_data.get("file", "")

                    if module_path in succ_file:
                        internal_deps.add(succ_file)
                    elif succ_file:
                        external_deps.add(succ_file)

        result_lines = [f"Module dependencies for '{module_path}':"]
        result_lines.append(f"  Files in module: {len(module_files)}")
        result_lines.append("")

        if internal_deps:
            result_lines.append("🔄 Internal dependencies:")
            for dep in sorted(internal_deps)[:15]:
                result_lines.append(f"  - {dep}")

        if external_deps:
            result_lines.append("\n📦 External dependencies:")
            for dep in sorted(external_deps)[:15]:
                result_lines.append(f"  - {dep}")

        metadata = {
            "relation_type": "module_dependency",
            "symbols_found": list(internal_deps | external_deps)[:20],
            "primary_file": module_path,
        }

        return "\n".join(result_lines), metadata

def is_loaded(self) -> bool:
        """检查图谱是否已加载"""
        return self.graph.number_of_nodes() > 0

def _detect_repo_language(repo_root: Path) -> str:
    """快速检测仓库主语言（只扫顶层文件，不递归）"""
    py_count = ts_count = 0
    for entry in repo_root.iterdir():
        if entry.is_file():
            if entry.suffix in _PYTHON_EXTENSIONS:
                py_count += 1
            elif entry.suffix in _TS_EXTENSIONS:
                ts_count += 1
    if py_count >= ts_count:
        return "python"
    return "typescript"

def _try_import_rope():
    try:
        import rope.base.project  # type: ignore
        import rope.contrib.findit  # type: ignore
        return True
    except ImportError:
        return False

def _rope_find_definition(
    repo_root: Path, symbol_name: str, file_hint: Optional[str] = None
) -> Optional[Dict[str, Any]]:
    """使用 rope 定位 Python 符号的定义位置"""
    try:
        import rope.base.project as rope_project
        import rope.contrib.findit as rope_findit

        project = rope_project.Project(str(repo_root))

        # 如果有 file_hint，先在该文件中尝试
        candidate_files: List[Path] = []
        if file_hint:
            hint_path = repo_root / file_hint
            if hint_path.exists():
                candidate_files.append(hint_path)

        # 扫描仓库找包含该符号名的 .py 文件（限速：最多扫 200 文件）
        scanned = 0
        for p in repo_root.rglob("*.py"):
            if scanned >= 200:
                break
            rel = str(p.relative_to(repo_root))
            skip_dirs = {".venv", "venv", "env", "node_modules", "__pycache__", ".git"}
            if any(part in skip_dirs for part in p.parts):
                continue
            try:
                text = p.read_text(encoding="utf-8", errors="ignore")
                if symbol_name in text:
                    candidate_files.append(p)
            except OSError:
                pass
            scanned += 1

        for py_file in candidate_files[:10]:
            try:
                resource = project.get_resource(str(py_file.relative_to(repo_root)))
                source = resource.read()
                # 找符号位置
                offset = source.find(f"def {symbol_name}")
                if offset == -1:
                    offset = source.find(f"class {symbol_name}")
                if offset == -1:
                    continue

                result = rope_findit.find_definition(project, resource, offset)
                if result:
                    def_resource = result.resource
                    line_no = result.lineno
                    return {
                        "definition_file": str(def_resource.path),
                        "definition_line": line_no,
                        "method": "rope",
                    }
            except Exception as inner_e:
                logger.debug("rope definition attempt failed for %s: %s", py_file, inner_e)
                continue

        project.close()
    except Exception as e:
        logger.debug("rope find_definition error: %s", e)
    return None

def _rope_find_references(
    repo_root: Path, symbol_name: str, file_hint: Optional[str] = None
) -> List[Dict[str, Any]]:
    """使用 rope 查找 Python 符号的所有引用"""
    refs: List[Dict[str, Any]] = []
    try:
        import rope.base.project as rope_project
        import rope.contrib.findit as rope_findit

        project = rope_project.Project(str(repo_root))

        # 找定义位置，再从定义位置出发调 find_occurrences
        def_info = _rope_find_definition(repo_root, symbol_name, file_hint)
        if def_info:
            def_file = repo_root / def_info["definition_file"]
            try:
                resource = project.get_resource(str(def_file.relative_to(repo_root)))
                source = resource.read()
                offset = source.find(f"def {symbol_name}")
                if offset == -1:
                    offset = source.find(f"class {symbol_name}")
                if offset >= 0:
                    occurrences = rope_findit.find_occurrences(project, resource, offset)
                    for occ in occurrences[:30]:
                        refs.append({
                            "file": str(occ.resource.path),
                            "line": occ.lineno,
                            "is_definition": occ.is_defined,
                        })
            except Exception as e:
                logger.debug("rope occurrences error: %s", e)

        project.close()
    except Exception as e:
        logger.debug("rope find_references error: %s", e)
    return refs

def _regex_find_definition(
    repo_root: Path, symbol_name: str, file_hint: Optional[str] = None
) -> Optional[Dict[str, Any]]:
    """
    正则扫描查找符号定义（支持 Python/TS/JS/Go/Rust 等）。
    匹配常见模式：def X, class X, function X, const X =, export function X, func X
    """
    patterns = [
        rf"(?:def|class)\s+{re.escape(symbol_name)}\b",           # Python
        rf"(?:function|class)\s+{re.escape(symbol_name)}\b",       # JS/TS
        rf"(?:const|let|var)\s+{re.escape(symbol_name)}\s*(?:=|:)", # JS/TS const
        rf"export\s+(?:function|class|const)\s+{re.escape(symbol_name)}\b",  # TS export
        rf"func\s+{re.escape(symbol_name)}\b",                     # Go
        rf"fn\s+{re.escape(symbol_name)}\b",                       # Rust
        rf"(?:public|private|protected|static).*\s{re.escape(symbol_name)}\s*\(", # Java/C#
    ]
    combined = re.compile("|".join(patterns), re.MULTILINE)

    candidate_files: List[Path] = []
    if file_hint:
        hint_path = repo_root / file_hint
        if hint_path.exists():
            candidate_files.append(hint_path)

    scanned = 0
    skip_dirs = {".venv", "venv", "env", "node_modules", "__pycache__", ".git", "dist", "build"}
    skip_exts = {".pyc", ".pyo", ".so", ".dylib", ".lock", ".min.js"}

    for p in repo_root.rglob("*"):
        if scanned >= 500:
            break
        if not p.is_file():
            continue
        if p.suffix in skip_exts:
            continue
        if any(part in skip_dirs for part in p.parts):
            continue
        if p.stat().st_size > 500_000:
            continue
        if symbol_name in p.read_text(encoding="utf-8", errors="ignore"):
            candidate_files.append(p)
        scanned += 1

    for src_file in candidate_files[:15]:
        try:
            text = src_file.read_text(encoding="utf-8", errors="ignore")
            for i, line in enumerate(text.splitlines(), 1):
                if combined.search(line):
                    return {
                        "definition_file": str(src_file.relative_to(repo_root)),
                        "definition_line": i,
                        "method": "regex",
                        "matched_line": line.strip()[:120],
                    }
        except OSError:
            continue
    return None

def _regex_find_references(
    repo_root: Path, symbol_name: str, max_refs: int = 30
) -> List[Dict[str, Any]]:
    """正则扫描查找符号引用"""
    refs: List[Dict[str, Any]] = []
    pattern = re.compile(rf"\b{re.escape(symbol_name)}\b")
    skip_dirs = {".venv", "venv", "env", "node_modules", "__pycache__", ".git", "dist", "build"}
    skip_exts = {".pyc", ".pyo", ".so", ".dylib", ".lock"}

    for p in repo_root.rglob("*"):
        if len(refs) >= max_refs:
            break
        if not p.is_file():
            continue
        if p.suffix in skip_exts:
            continue
        if any(part in skip_dirs for part in p.parts):
            continue
        if p.stat().st_size > 300_000:
            continue
        try:
            text = p.read_text(encoding="utf-8", errors="ignore")
            if symbol_name not in text:
                continue
            for i, line in enumerate(text.splitlines(), 1):
                if pattern.search(line):
                    refs.append({
                        "file": str(p.relative_to(repo_root)),
                        "line": i,
                        "snippet": line.strip()[:100],
                    })
                    if len(refs) >= max_refs:
                        break
        except OSError:
            continue
    return refs

class LSPResolveTool:
    """
    LSP 符号精确解析工具。

    不启动 LSP server 进程，使用：
    - rope（Python 仓库的静态分析）
    - 正则扫描 fallback（所有其他语言）
    """

    def __init__(self, repo_root: str):
        self.repo_root = Path(repo_root).resolve()
        self._lang = _detect_repo_language(self.repo_root)
        self._has_rope = _try_import_rope()
        logger.info(
            "[LSPResolveTool] repo_root=%s lang=%s rope=%s",
            self.repo_root, self._lang, self._has_rope,
        )

    def execute(
        self,
        symbol_name: str,
        operation: str = "find_definition",
        file_hint: Optional[str] = None,
    ) -> ContextPiece:
        """
        执行 LSP 解析操作。

        Args:
            symbol_name: 要查找的符号名（函数名、类名等）
            operation: "find_definition" | "find_references" | "hover"
            file_hint: 可选的起始文件路径（加速搜索）

        Returns:
            ContextPiece，包含解析结果和定位元数据
        """
        if not symbol_name or not symbol_name.strip():
            return ContextPiece(
                source="lsp_resolve",
                content="Empty symbol name provided.",
                relevance_score=0.0,
                metadata={"error": "empty_symbol"},
            )

        operation = operation.strip().lower()
        if operation not in _SUPPORTED_OPERATIONS:
            operation = "find_definition"

        symbol_name = symbol_name.strip()

        if operation == "find_definition":
            return self._find_definition(symbol_name, file_hint)
        elif operation == "find_references":
            return self._find_references(symbol_name, file_hint)
        else:  # hover
            return self._hover(symbol_name, file_hint)

    def _find_definition(self, symbol_name: str, file_hint: Optional[str]) -> ContextPiece:
        def_info: Optional[Dict[str, Any]] = None

        # Python repos: try rope first
        if self._lang == "python" and self._has_rope:
            def_info = _rope_find_definition(self.repo_root, symbol_name, file_hint)

        # Fallback: regex scan
        if not def_info:
            def_info = _regex_find_definition(self.repo_root, symbol_name, file_hint)

        if def_info:
            rel_file = def_info["definition_file"]
            line_no = def_info["definition_line"]
            method = def_info.get("method", "regex")
            matched = def_info.get("matched_line", "")

            content_lines = [
                f"**Symbol**: `{symbol_name}`",
                f"**Definition found at**: `{rel_file}` line {line_no}",
            ]
            if matched:
                content_lines.append(f"**Definition line**: `{matched}`")

            content = "\n".join(content_lines)
            return ContextPiece(
                source="lsp_resolve",
                content=content,
                file_path=rel_file,
                line_range=(line_no, line_no),
                relevance_score=0.95 if method == "rope" else 0.88,
                metadata={
                    "operation": "find_definition",
                    "symbol_name": symbol_name,
                    "definition_file": rel_file,
                    "definition_line": line_no,
                    "method": method,
                },
            )
        else:
            return ContextPiece(
                source="lsp_resolve",
                content=f"Could not locate definition of `{symbol_name}` in repository.",
                relevance_score=0.0,
                metadata={
                    "operation": "find_definition",
                    "symbol_name": symbol_name,
                    "method": "not_found",
                },
            )

    def _find_references(self, symbol_name: str, file_hint: Optional[str]) -> ContextPiece:
        refs: List[Dict[str, Any]] = []

        if self._lang == "python" and self._has_rope:
            refs = _rope_find_references(self.repo_root, symbol_name, file_hint)

        if not refs:
            refs = _regex_find_references(self.repo_root, symbol_name)

        if refs:
            # Group by file
            by_file: Dict[str, List[Dict]] = {}
            for r in refs:
                f = r["file"]
                by_file.setdefault(f, []).append(r)

            lines = [f"**Symbol**: `{symbol_name}` — {len(refs)} reference(s) across {len(by_file)} file(s)\n"]
            for f, file_refs in list(by_file.items())[:10]:
                line_nums = ", ".join(str(r["line"]) for r in file_refs[:5])
                lines.append(f"- `{f}` lines [{line_nums}]")

            content = "\n".join(lines)
            return ContextPiece(
                source="lsp_resolve",
                content=content,
                relevance_score=0.85,
                metadata={
                    "operation": "find_references",
                    "symbol_name": symbol_name,
                    "references_count": len(refs),
                    "files_count": len(by_file),
                    "references": refs[:20],
                    "method": "rope" if (self._lang == "python" and self._has_rope) else "regex",
                },
            )
        else:
            return ContextPiece(
                source="lsp_resolve",
                content=f"No references found for `{symbol_name}`.",
                relevance_score=0.0,
                metadata={
                    "operation": "find_references",
                    "symbol_name": symbol_name,
                    "method": "not_found",
                },
            )

    def _hover(self, symbol_name: str, file_hint: Optional[str]) -> ContextPiece:
        """Hover: 返回符号定义行及上下文（约 5 行）"""
        def_info = None

        if self._lang == "python" and self._has_rope:
            def_info = _rope_find_definition(self.repo_root, symbol_name, file_hint)

        if not def_info:
            def_info = _regex_find_definition(self.repo_root, symbol_name, file_hint)

        if not def_info:
            return ContextPiece(
                source="lsp_resolve",
                content=f"Could not find hover info for `{symbol_name}`.",
                relevance_score=0.0,
                metadata={"operation": "hover", "symbol_name": symbol_name, "method": "not_found"},
            )

        rel_file = def_info["definition_file"]
        line_no = int(def_info["definition_line"])
        method = def_info.get("method", "regex")

        # Read surrounding lines for context
        full_path = self.repo_root / rel_file
        snippet_lines: List[str] = []
        try:
            all_lines = full_path.read_text(encoding="utf-8", errors="ignore").splitlines()
            start = max(0, line_no - 1)
            end = min(len(all_lines), start + 10)
            snippet_lines = all_lines[start:end]
        except OSError:
            pass

        snippet = "\n".join(snippet_lines) if snippet_lines else def_info.get("matched_line", "")
        content = (
            f"**Symbol**: `{symbol_name}` at `{rel_file}:{line_no}`\n\n"
            f"```\n{snippet}\n```"
        )
        return ContextPiece(
            source="lsp_resolve",
            content=content,
            file_path=rel_file,
            line_range=(line_no, line_no + len(snippet_lines)),
            relevance_score=0.90 if method == "rope" else 0.82,
            metadata={
                "operation": "hover",
                "symbol_name": symbol_name,
                "definition_file": rel_file,
                "definition_line": line_no,
                "method": method,
            },
        )

def execute(
        self,
        symbol_name: str,
        operation: str = "find_definition",
        file_hint: Optional[str] = None,
    ) -> ContextPiece:
        """
        执行 LSP 解析操作。

        Args:
            symbol_name: 要查找的符号名（函数名、类名等）
            operation: "find_definition" | "find_references" | "hover"
            file_hint: 可选的起始文件路径（加速搜索）

        Returns:
            ContextPiece，包含解析结果和定位元数据
        """
        if not symbol_name or not symbol_name.strip():
            return ContextPiece(
                source="lsp_resolve",
                content="Empty symbol name provided.",
                relevance_score=0.0,
                metadata={"error": "empty_symbol"},
            )

        operation = operation.strip().lower()
        if operation not in _SUPPORTED_OPERATIONS:
            operation = "find_definition"

        symbol_name = symbol_name.strip()

        if operation == "find_definition":
            return self._find_definition(symbol_name, file_hint)
        elif operation == "find_references":
            return self._find_references(symbol_name, file_hint)
        else:  # hover
            return self._hover(symbol_name, file_hint)

