def _domain_allowed(url: str, allowed_domains: Optional[List[str]]) -> bool:
    """检查 URL 域是否在白名单内（空白名单 = 全部允许）"""
    if not allowed_domains:
        return True
    try:
        host = urlparse(url).netloc.lower()
        # 去掉 www. 前缀
        if host.startswith("www."):
            host = host[4:]
        return any(host == d or host.endswith("." + d) for d in allowed_domains)
    except Exception:
        return False

def _truncate(text: str, max_chars: int = _MAX_SNIPPET_CHARS) -> str:
    if len(text) <= max_chars:
        return text
    return text[:max_chars].rstrip() + "…"

def _search_duckduckgo(
    query: str,
    max_results: int,
    timeout: int,
    allowed_domains: Optional[List[str]],
) -> List[Dict[str, str]]:
    """使用 duckduckgo-search 包查询（无需 API key）"""
    try:
        from duckduckgo_search import DDGS  # type: ignore
    except ImportError:
        logger.warning("[WebSearch] duckduckgo_search not installed. Run: pip install duckduckgo-search")
        return []

    results: List[Dict[str, str]] = []
    try:
        with DDGS() as ddgs:
            for r in ddgs.text(query, max_results=max_results * 2):
                url = r.get("href") or r.get("link") or ""
                if allowed_domains and not _domain_allowed(url, allowed_domains):
                    continue
                results.append({
                    "title": r.get("title", ""),
                    "url": url,
                    "snippet": _truncate(r.get("body", "") or r.get("snippet", "")),
                })
                if len(results) >= max_results:
                    break
    except Exception as e:
        logger.warning("[WebSearch] DuckDuckGo search failed: %s", e)
    return results

def _search_tavily(
    query: str,
    max_results: int,
    timeout: int,
    allowed_domains: Optional[List[str]],
    api_key: str,
    search_depth: str = "basic",
) -> List[Dict[str, str]]:
    """使用 Tavily API 查询"""
    try:
        from tavily import TavilyClient  # type: ignore
        client = TavilyClient(api_key=api_key)
        response = client.search(
            query=query,
            search_depth=search_depth,
            max_results=max_results * 2,
        )
        results: List[Dict[str, str]] = []
        for r in response.get("results", []):
            url = r.get("url", "")
            if allowed_domains and not _domain_allowed(url, allowed_domains):
                continue
            results.append({
                "title": r.get("title", ""),
                "url": url,
                "snippet": _truncate(r.get("content", "") or r.get("snippet", "")),
            })
            if len(results) >= max_results:
                break
        return results
    except ImportError:
        logger.warning("[WebSearch] tavily package not installed. Run: pip install tavily-python")
        return []
    except Exception as e:
        logger.warning("[WebSearch] Tavily search failed: %s", e)
        return []

def _search_serpapi(
    query: str,
    max_results: int,
    timeout: int,
    allowed_domains: Optional[List[str]],
    api_key: str,
) -> List[Dict[str, str]]:
    """使用 SerpAPI 查询"""
    try:
        import requests  # type: ignore
        params = {
            "q": query,
            "api_key": api_key,
            "num": max_results * 2,
            "engine": "google",
        }
        resp = requests.get(
            "https://serpapi.com/search",
            params=params,
            timeout=timeout,
        )
        resp.raise_for_status()
        data = resp.json()
        results: List[Dict[str, str]] = []
        for r in data.get("organic_results", []):
            url = r.get("link", "")
            if allowed_domains and not _domain_allowed(url, allowed_domains):
                continue
            results.append({
                "title": r.get("title", ""),
                "url": url,
                "snippet": _truncate(r.get("snippet", "")),
            })
            if len(results) >= max_results:
                break
        return results
    except ImportError:
        logger.warning("[WebSearch] requests not installed.")
        return []
    except Exception as e:
        logger.warning("[WebSearch] SerpAPI search failed: %s", e)
        return []

def _enhance_query(query: str, search_type: str) -> str:
        """根据 search_type 增强查询语境"""
        if search_type == "version":
            if "latest" not in query.lower() and "version" not in query.lower():
                return f"{query} latest stable version"
        elif search_type == "cve":
            if "cve" not in query.lower() and "vulnerability" not in query.lower():
                return f"{query} CVE security vulnerability"
        elif search_type == "code_docs":
            if "documentation" not in query.lower() and "docs" not in query.lower():
                return f"{query} documentation API reference"
        return query

class SupabaseClient:
    def __init__(
        self,
        supabase_url: Optional[str] = None,
        supabase_key: Optional[str] = None,
    ):
        self.url = supabase_url or os.getenv("SUPABASE_URL")
        self.key = supabase_key or os.getenv("SUPABASE_KEY")

        if not self.url or not self.key:
            print("[Supabase] Warning: SUPABASE_URL or SUPABASE_KEY not set.")
            self.client = None
        else:
            self.client = create_client(self.url, self.key)

    def _normalize_repo_url(self, repo_url: str) -> str:
        """
        Normalize repository URL to stable canonical format.
        """
        if not repo_url:
            return ""
        raw = repo_url.strip()
        if not raw:
            return ""

        # Support ssh format: git@github.com:owner/repo(.git)
        if raw.startswith("git@") and ":" in raw:
            host_and_path = raw.split("@", 1)[1]
            host, path = host_and_path.split(":", 1)
            path = path.strip().rstrip("/")
            if path.endswith(".git"):
                path = path[:-4]
            parts = [p for p in path.split("/") if p]
            if len(parts) >= 2:
                return f"https://{host.lower()}/{parts[0].lower()}/{parts[1].lower()}"

        parsed = urlsplit(raw)
        if parsed.netloc:
            host = parsed.netloc.lower()
            path = parsed.path.strip().rstrip("/")
            if path.endswith(".git"):
                path = path[:-4]
            parts = [p for p in path.split("/") if p]
            if len(parts) >= 2:
                scheme = parsed.scheme.lower() if parsed.scheme else "https"
                return f"{scheme}://{host}/{parts[0].lower()}/{parts[1].lower()}"

            # No owner/repo shape, fallback to cleaned URL
            scheme = parsed.scheme.lower() if parsed.scheme else "https"
            return f"{scheme}://{host}{path}".rstrip("/")

        # Fallback for plain strings
        normalized = raw.rstrip("/")
        if normalized.endswith(".git"):
            normalized = normalized[:-4]
        return normalized.lower()

    def _extract_repo_key(self, normalized_repo_url: str) -> str:
        """
        Extract 'owner/repo' key from normalized URL.
        """
        parsed = urlsplit(normalized_repo_url)
        parts = [p for p in parsed.path.split("/") if p]
        if len(parts) >= 2:
            return f"{parts[0].lower()}/{parts[1].lower()}"
        return ""

    def update_repository_vector_path(self, repo_url: str, vector_store_path: str):
        """
        Update or insert the vector_store_path for a repository in Supabase using upsert.
        """
        if not self.client:
            print("[Supabase] Client not initialized. Skipping update.")
            return False

        repo_url = self._normalize_repo_url(repo_url)
        try:
            # Use upsert to either update an existing record or insert a new one
            # The 'repo_url' is the primary key, so upsert will use it to match
            self.client.table("repositories").upsert({
                "repo_url": repo_url,
                "vector_store_path": vector_store_path,
                "last_updated": "now()"
            }).execute()

            print(f"[Supabase] Upserted repository record (vector path) for {repo_url}")
            return True
        except Exception as e:
            print(f"[Supabase] Error updating repository (upsert): {e}")
            return False

    def create_task(self, user_id: str, task_id: str, repo_url: str):
        """
        Create a new task in Supabase.
